/**
 * Subset of Noto Sans containing U+20B5 (Ghana cedi) plus Latin/punctuation.
 * Embedded as a data URI so Chromium PDF rendering does not depend on
 * serverless font availability or Open Sans glyph coverage.
 */
export const DOCUMENT_FONT_FAMILY = "FinzaDocument"

export const DOCUMENT_FONT_FACE_CSS = `
@font-face {
  font-family: 'FinzaDocument';
  font-style: normal;
  font-weight: 400;
  src: url(data:font/woff2;base64,) format('woff2');
}
@font-face {
  font-family: 'FinzaDocument';
  font-style: normal;
  font-weight: 700;
  src: url(data:font/woff2;base64,) format('woff2');
}
`
